data.verdict:
{
  "causes": [
    {
      "cause": "The capped basket used the same offer geometry on Saturday and Thursday, so the day sweep showed one saving twice and the 'which day' screen had nothing to decide.",
      "earliest_signal": "test_day_sweep passed while both discounts were equal.",
      "prevention": "AC 3 requires Keells Saturday discount to equal cap_lkr and Keells Thursday discount to be 0, on the same shelf prices.",
      "interrogation_question": "Should Thursday on the capped basket be a zero-saving day so the day comparison is visible?"
    },
    {
      "cause": "The explanation endpoint returned a sentence with no digits, and the subset check passed without ever stating the legal saving.",
      "earliest_signal": "test_explanation_numbers_subset_of_plan passed on the string 'See the plan.'",
      "prevention": "AC 5 requires the explanation to contain the plan discount digits and no number absent from the plan JSON.",
      "interrogation_question": "Must the explanation include the discount figure, not merely avoid extra numbers?"
    },
    {
      "cause": "Approve returned mock true plus a partner host with no URL scheme, and the http/https ban still passed.",
      "earliest_signal": "The approve test passed on {\"mock\": true, \"handoff\": \"keells.example\"}.",
      "prevention": "AC 8 allows only the keys preview_id and mock.",
      "interrogation_question": "Should the approve body be exactly those two fields?"
    },
    {
      "cause": "Judges only ever saw fixture lines. The extract route was unwired, and a later upload of a real receipt was written to a public bucket.",
      "earliest_signal": "No test called the model client, and a receipt object appeared in storage.",
      "prevention": "AC 11 requires the extract route to call the model with the image bytes and a JSON schema, to write those bytes nowhere, and to return 429 on the 31st call in that process-minute.",
      "interrogation_question": "Is a fake-client test of that route enough for this prototype, with the live key used only on Cloud Run?"
    },
    {
      "cause": "A client posted a plan JSON with an inflated discount and the explain route narrated it.",
      "earliest_signal": "Explain request logs showed a discount that was not in the optimizer output.",
      "prevention": "The explain API recomputes the plan on the server and ignores a client-supplied discount.",
      "interrogation_question": "Already closed: server-side recompute. Any objection?"
    },
    {
      "cause": "The public extract route was called in a loop through evaluation and the Gemini bill spiked.",
      "earliest_signal": "Cloud Run request count on POST /v1/receipts far above judge traffic.",
      "prevention": "AC 11's 429 at 31 calls per process-minute, plus Cloud Run minimum instances 0.",
      "interrogation_question": "Is a per-process limit of 30 extracts per minute acceptable for the demo?"
    }
  ]
}

